import type { PatientInput, PredictResponse } from "./api";

// General, widely accepted lifestyle guidance for lowering type 2 diabetes risk
// (consistent with public ADA / WHO / NHS advice). It is chosen by rules from the
// assessment, NOT generated by the ML model, and is not personal medical advice.

export type PlanItem = { id: string; title: string; why: string };

export type Plan = {
  daily: PlanItem[];
  soon: string[];
  precautions: string[];
  urgent: string;
};

export function buildPlan(input: PatientInput, result: PredictResponse): Plan {
  const flagged = result.flagged_higher_risk;
  const raisedBy = (f: string) => result.factors.some((x) => x.feature === f && x.impact > 0);

  const glucoseHigh = (input.Glucose ?? 0) >= 100 || raisedBy("Glucose");
  const bmiHigh = (input.BMI ?? 0) >= 25 || raisedBy("BMI");

  const daily: PlanItem[] = [];

  if (glucoseHigh || flagged) {
    daily.push(
      {
        id: "drinks",
        title: "Swap sugary drinks for water or unsweetened tea",
        why: "Sweet drinks cause the fastest blood-sugar spikes. Glucose is the biggest factor in your score.",
      },
      {
        id: "plate",
        title: "Fill half your plate with vegetables; choose whole grains over white rice, bread or sweets",
        why: "Fibre slows how fast sugar enters the blood.",
      },
      {
        id: "walk",
        title: "Take a 10 to 15 minute walk after your biggest meal",
        why: "Light movement after eating helps your muscles use up glucose.",
      },
    );
  }

  if (bmiHigh) {
    daily.push({
      id: "move",
      title: "Be active for 30 minutes (brisk walking, cycling, dancing, swimming)",
      why: "150 minutes a week is the standard target. Even modest weight loss (5 to 7% of body weight) has been shown to lower the chance of developing type 2 diabetes.",
    });
  }

  daily.push(
    {
      id: "sleep",
      title: "Sleep 7 to 9 hours",
      why: "Poor sleep is linked to higher blood sugar and weight gain.",
    },
    {
      id: "meals",
      title: "Eat at regular times and avoid late-night snacking",
      why: "Steady meals help keep blood sugar stable.",
    },
  );

  if (!glucoseHigh && !bmiHigh && !flagged) {
    daily.unshift({
      id: "keep",
      title: "Keep up what you are doing: move most days and keep sweet drinks occasional",
      why: "Your score is on the lower side. These habits help it stay there.",
    });
  }

  const soon: string[] = [];
  if (flagged) {
    soon.push(
      "Book a blood test (fasting glucose or HbA1c) with a doctor and show them this result. Only a test can confirm or rule out diabetes.",
    );
  } else {
    soon.push("Repeat screening as your doctor advises, and sooner if your weight, family history or symptoms change.");
  }
  if (result.not_measured.length > 0) {
    soon.push(
      "Ask for the missing measurements (for example glucose and BMI) next time. The score is more reliable with real values than with typical ones.",
    );
  }
  if (input.Pregnancies > 0 || input.Age >= 35) {
    soon.push("If you are or become pregnant, follow your care team's glucose screening schedule.");
  }
  soon.push("Do not stop or change any medicine you have been prescribed without asking your doctor.");

  const precautions = [
    "Being very thirsty or urinating much more often than usual",
    "Blurry vision",
    "Feeling unusually tired",
    "Losing weight without trying",
    "Cuts or sores that heal slowly, or frequent infections",
    "Numbness or tingling in your hands or feet",
  ];

  return {
    daily,
    soon,
    precautions,
    urgent:
      "Seek urgent medical care if you have vomiting, fast deep breathing, confusion, or extreme drowsiness together with high thirst or very high blood sugar.",
  };
}
